import { Component, OnInit, signal, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import {
  FormBuilder,
  FormGroup,
  Validators,
  ReactiveFormsModule,
} from '@angular/forms';
import { Router } from '@angular/router';
import {
  ProfileService,
  UserProfile,
  ProfileUpdateRequest,
} from '../../services/profile.service';
import { ImageService } from '../../services/image.service';
import { TranslationService } from '../../services/translation.service';
import { LangService } from '../../services/lang.service';

@Component({
  selector: 'app-profile',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './profile.component.html',
  styleUrls: ['./profile.component.css'],
})
export class ProfileComponent implements OnInit, OnDestroy {
  profile = signal<UserProfile | null>(null);
  loading = signal(false);
  saving = signal(false);
  currentLang = signal<'ar' | 'en'>('en');
  isRTLDirection = signal(false);

  // Success modal state
  showSuccessModal = signal(false);
  successMessage = signal('');

  // Image preview state
  selectedImagePreview = signal<string | null>(null);
  selectedFile: File | null = null;

  profileForm: FormGroup;

  constructor(
    private profileService: ProfileService,
    private imageService: ImageService,
    private fb: FormBuilder,
    private translationService: TranslationService,
    private langService: LangService,
    private router: Router
  ) {
    this.profileForm = this.fb.group({
      firstName: ['', [Validators.required, Validators.minLength(2)]],
      lastName: ['', [Validators.required, Validators.minLength(2)]],
      phoneNumber: ['', [Validators.required, Validators.minLength(5)]], // More permissive phone validation
    });
  }

  ngOnInit(): void {
    this.loadProfile();
    this.langService.currentLang$.subscribe((lang) => {
      this.currentLang.set(lang);
      this.isRTLDirection.set(lang === 'ar');
    });
  }

  ngOnDestroy(): void {
    // Cleanup subscriptions if any
  }

  loadProfile(): void {
    this.loading.set(true);
    this.profileService.getProfile().subscribe({
      next: (response) => {
        if (response.success) {
          this.profile.set(response.data);
          this.populateForm(response.data);
        }
        this.loading.set(false);
      },
      error: (error) => {
        this.loading.set(false);
      },
    });
  }

  populateForm(profileData: UserProfile): void {

    // Check for different possible phone number property names
    const phoneValue =
      profileData.phoneNumber ||
      (profileData as any).phone ||
      (profileData as any).phoneNumber ||
      (profileData as any).PhoneNumber ||
      '';


    const formData = {
      firstName: profileData.firstName,
      lastName: profileData.lastName,
      phoneNumber: phoneValue,
    };


    this.profileForm.patchValue(formData);

  }

  onSubmit(): void {


    if (this.profileForm.valid && this.profile()) {
      this.saving.set(true);

      // Convert image to base64 if selected
      if (this.selectedFile) {
        const reader = new FileReader();
        reader.onload = (e) => {
          const base64Image = e.target?.result as string;
          this.updateProfileWithImage(base64Image);
        };
        reader.readAsDataURL(this.selectedFile);
      } else {
        // Update without image
        this.updateProfileWithoutImage();
      }
    } else {
      // Mark all fields as touched to show validation errors
      this.markFormGroupTouched();
    }
  }

  private markFormGroupTouched(): void {
    Object.keys(this.profileForm.controls).forEach((key) => {
      const control = this.profileForm.get(key);
      control?.markAsTouched();
    });
  }

  private base64ToBinary(base64: string): string {
    // Remove data URL prefix if present
    const base64Data = base64.includes(',') ? base64.split(',')[1] : base64;

    // Convert base64 to binary string
    const binaryString = atob(base64Data);
    return binaryString;
  }

  private base64ToBlob(base64: string): Blob {
    // Remove data URL prefix if present
    const base64Data = base64.includes(',') ? base64.split(',')[1] : base64;

    // Convert base64 to binary
    const binaryString = atob(base64Data);
    const bytes = new Uint8Array(binaryString.length);

    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }

    // Determine MIME type from base64 prefix
    const mimeType = base64.match(/data:([^;]+);/)?.[1] || 'image/png';

    return new Blob([bytes], { type: mimeType });
  }

  private updateProfileWithImage(base64Image: string): void {
    // Create FormData for multipart/form-data request
    const formData = new FormData();

    // Use PascalCase field names as expected by API
    formData.append('FirstName', this.profileForm.get('firstName')?.value);
    formData.append('LastName', this.profileForm.get('lastName')?.value);
    formData.append('PhoneNumber', this.profileForm.get('phoneNumber')?.value);

    // Convert base64 to blob and append as file
    const blob = this.base64ToBlob(base64Image);
    formData.append('NewImage', blob, 'profile-image.png');

    this.profileService.updateProfileWithFormData(formData).subscribe({
      next: (response) => {
        this.handleUpdateSuccess(response);
      },
      error: (error) => {
        console.error('Error updating profile with image:', error);
        this.saving.set(false);
      },
    });
  }

  private updateProfileWithoutImage(): void {
    // Create FormData for multipart/form-data request
    const formData = new FormData();

    // Use PascalCase field names as expected by API
    formData.append('FirstName', this.profileForm.get('firstName')?.value);
    formData.append('LastName', this.profileForm.get('lastName')?.value);
    formData.append('PhoneNumber', this.profileForm.get('phoneNumber')?.value);

    this.profileService.updateProfileWithFormData(formData).subscribe({
      next: (response) => {
        this.handleUpdateSuccess(response);
      },
      error: (error) => {
        console.error('Error updating profile:', error);
        this.saving.set(false);
      },
    });
  }

  private handleUpdateSuccess(response: any): void {

    
    if (response.success) {
      this.profile.set(response.data);
      this.populateForm(response.data);

      // Clear the preview and selected file after successful update
      this.selectedImagePreview.set(null);
      this.selectedFile = null;

      // Show success modal
      this.successMessage.set(this.translate('profile.update_success'));
      this.showSuccessModal.set(true);

      // Auto-hide after 3 seconds
      setTimeout(() => {
        this.showSuccessModal.set(false);
      }, 3000);
    } else {
      console.error('Update failed:', response.message || 'Unknown error');
    }
    this.saving.set(false);
  }

  triggerImageUpload(): void {
    // This would trigger the file input
    const fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = 'image/*';
    fileInput.onchange = (event) => this.onImageChange(event);
    fileInput.click();
  }

  onImageChange(event: Event): void {
    const target = event.target as HTMLInputElement;
    if (target.files && target.files.length > 0) {
      const file = target.files[0];
      this.selectedFile = file;

      // Create preview URL
      const reader = new FileReader();
      reader.onload = (e) => {
        this.selectedImagePreview.set(e.target?.result as string);
      };
      reader.readAsDataURL(file);

      console.log('Image selected:', file);
    }
  }

  removeImagePreview(): void {
    this.selectedImagePreview.set(null);
    this.selectedFile = null;
  }

  getDisplayImageUrl(): string {
    // If there's a preview, show it; otherwise show the current profile image
    if (this.selectedImagePreview()) {
      return this.selectedImagePreview()!;
    }
    return this.getUserImageUrl();
  }

  getFullName(): string {
    const profileData = this.profile();
    if (profileData) {
      return `${profileData.firstName} ${profileData.lastName}`;
    }
    return '';
  }

  showSuccessMessage(): boolean {
    return this.showSuccessModal();
  }

  hideSuccessMessage(): void {
    this.showSuccessModal.set(false);
  }

  translate(key: string): string {
    return this.translationService.translate(key);
  }

  isRTL(): boolean {
    return this.translationService.isRTL();
  }

  getUserImageUrl(): string {
    const profileData = this.profile();
    if (profileData) {
      return this.imageService.getImageUrl(
        profileData.imageUrl,
        `${profileData.firstName} ${profileData.lastName}`
      );
    }
    return this.imageService.getImageUrl();
  }

  getUserInitials(): string {
    const profileData = this.profile();
    if (profileData) {
      return this.imageService.getUserInitials(
        profileData.firstName,
        profileData.lastName
      );
    }
    return 'U';
  }

  navigateToChangePassword(): void {
    this.router.navigate(['/auth/change-password']);
  }
}
